"""Add drug-susceptible TB regimens and medication safety."""
from create_tb_diagnosis import rows,q,WD,WT,AD,CD,IG,NG
from qbank_authoring import ref,finalize
DS=ref('CDC: Treatment for Drug-Susceptible TB Disease','https://www.cdc.gov/tb/hcp/treatment/tuberculosis-disease.html')
UP=ref('ATS/CDC/ERS/IDSA TB Treatment Update, 2025','https://pmc.ncbi.nlm.nih.gov/articles/PMC11755361/')
AE=ref('CDC: Adverse Events During TB Treatment','https://www.cdc.gov/tb/hcp/treatment/adverse-events.html')
PG=ref('CDC: TB Clinical Care During Pregnancy','https://www.cdc.gov/tb/hcp/clinical-care/pregnancy.html')
OT=ref('ATS/CDC/IDSA: Treatment of Drug-Susceptible TB','https://pmc.ncbi.nlm.nih.gov/articles/PMC6590850/')
q('In the standard six-month CDC regimen for uncomplicated drug-susceptible pulmonary TB, which intensive phase is used?', 'Two months of isoniazid, rifampicin, pyrazinamide and ethambutol',[
 ('Isoniazid alone for two months','Monotherapy is inadequate for active TB.'),('Rifampicin and ethambutol alone for one week','This is not adequate multidrug treatment.'),('Bedaquiline and linezolid alone for every susceptible case','These are not the standard first-line intensive phase.')],
 'Active TB requires a complete multidrug regimen', '**The standard intensive phase is abbreviated 2HRZE.**',['The usual CDC continuation phase uses isoniazid and rifampicin.','National program details and special disease sites can differ.'], '**Select the regimen from susceptibility and eligibility.**',['Shorter regimens exist for selected patients.','Do not extrapolate a pulmonary regimen to every CNS or resistant case.'],[['H','Isoniazid'],['R','Rifampicin'],['Z and E','Pyrazinamide and ethambutol']],[DS,WT])
q('Which four-month option can be used for eligible drug-susceptible pulmonary TB patients aged at least 12 years?', 'A rifapentine–moxifloxacin-containing regimen with isoniazid and initial pyrazinamide',[
 ('Simply stop the standard six-month regimen after month four in every adult','A validated shorter regimen is not the same as prematurely stopping standard treatment.'),('Four months of isoniazid alone for active disease','This is inadequate.'),('A four-month regimen for all TB meningitis without site-specific assessment','The pulmonary eligibility criteria do not cover every disease site.')],
 'Shorter treatment requires the tested drug combination and eligibility', '**The regimen is commonly described as 2HPZM/2HPM.**',['Weight, pregnancy, interactions and drug susceptibility affect eligibility.','Moxifloxacin and rifapentine have important safety and interaction considerations.'], '**Use the current national or local implementation pathway.**',['The standard six-month regimen remains an option.','Do not use this regimen where relevant resistance or exclusions are present.'],[['Short regimen','Rifapentine and moxifloxacin based'],['Eligibility','Pulmonary disease and specified patient criteria'],['Not equivalent','Arbitrary truncation of standard therapy']],[UP,DS])
q('Why should multiple active drugs be used together for TB disease?', 'To treat different bacterial populations and prevent selection of resistant subpopulations',[
 ('To ensure one drug can always be omitted without assessment','Loss of an active drug can compromise the regimen.'),('Because all TB drugs have identical mechanisms and resistance pathways','Their activities and resistance mechanisms differ.'),('To make susceptibility testing unnecessary','Regimen effectiveness still depends on susceptibility.')],
 'Large bacterial populations can contain resistant mutants', '**Inadequate drug combinations select resistance.**',['Different drugs contribute bactericidal and sterilizing activity.','Adherence and reliable drug delivery are essential.'], '**Avoid adding a single drug to a failing regimen.**',['Reconstruct an effective combination using susceptibility and treatment history.','Address the practical cause of inadequate exposure.'],[['Combination','Multiple active mechanisms'],['Inadequate exposure','Resistance selection risk'],['Failure','Reassess the entire regimen']],[WT,OT])
q('A patient taking isoniazid has diabetes and poor nutrition. Which supplement helps prevent peripheral neuropathy?', 'Pyridoxine',[
 ('Folic acid as the specific replacement for isoniazid-associated B6 effects','Folate does not replace the relevant vitamin B6 intervention.'),('Vitamin K','It does not prevent isoniazid-associated neuropathy.'),('Vitamin B12 without assessing or addressing B6 needs','B12 deficiency is a separate neuropathy mechanism.')],
 'Isoniazid can interfere with pyridoxine metabolism', '**Patients with neuropathy risk should receive appropriate B6 supplementation.**',['Risk includes pregnancy, malnutrition, diabetes and selected chronic illnesses.','New neuropathy still needs evaluation for competing causes.'], '**Use a suitable dose and follow the clinical response.**',['Excess pyridoxine can itself cause neuropathy.','Review adherence and avoid unsupervised high-dose supplementation.'],[['Drug','Isoniazid'],['Prevention','Pyridoxine'],['Assessment','Risk factors and alternative neuropathy causes']],[OT],style='clinical_scenario')
q('A patient receiving ethambutol develops blurred central vision and impaired red–green discrimination. What is the best next action?', 'Stop ethambutol promptly and arrange urgent ophthalmic and TB-regimen review',[
 ('Continue unchanged until blindness occurs','Possible optic toxicity requires prompt action.'),('Attribute the symptoms to harmless orange tear discoloration','Rifamycin discoloration does not explain central visual dysfunction.'),('Treat only with pyridoxine while continuing ethambutol','B6 does not reliably prevent ethambutol optic neuropathy.')],
 'Vision symptoms are a serious ethambutol safety signal', '**Ethambutol can cause optic neuropathy.**',['Renal impairment can increase exposure.','Baseline and follow-up visual assessment support safe use.'], '**Maintain an effective TB regimen while addressing toxicity.**',['Arrange a suitable replacement strategy with the treating team.','Do not wait for severe irreversible loss before acting.'],[['Clue','Central acuity and color change'],['Drug','Ethambutol'],['Action','Stop and urgently assess']],[AE,OT],style='clinical_scenario')
q('Which first-line TB drug is especially associated with hyperuricemia and arthralgia?', 'Pyrazinamide',[
 ('Ethambutol as the only drug capable of affecting urate','Ethambutol can also affect urate, but pyrazinamide is the characteristic major association.'),('Isoniazid as the primary uricosuric drug','That is not its characteristic pharmacology.'),('Rifampicin as the specific cause of every elevated uric acid level','This is not a specific rifampicin signature.')],
 'A biochemical adverse effect does not automatically require drug withdrawal', '**Pyrazinamide can reduce urate excretion and cause arthralgia.**',['Asymptomatic hyperuricemia is common.','Acute gout or severe symptoms require individualized management.'], '**Assess the clinical consequence and alternative causes.**',['Do not stop a useful drug solely for a modest asymptomatic laboratory rise without review.','Other toxicity, especially hepatic injury, needs separate assessment.'],[['Drug','Pyrazinamide'],['Effect','Hyperuricemia/arthralgia'],['Decision','Clinical severity rather than urate alone']],[OT,AE])
q('A patient on HRZE develops anorexia, vomiting and jaundice with substantial aminotransferase elevation. What is the best principle?', 'Promptly stop potentially hepatotoxic agents and arrange urgent assessment with a safe TB-treatment plan',[
 ('Continue all drugs unchanged because hepatitis is always harmless','Symptomatic hepatic injury can be serious.'),('Stop ethambutol alone and continue every hepatotoxic drug automatically','Ethambutol is not the main hepatotoxic component.'),('Restart all drugs at once without evaluation as soon as jaundice appears','Cause assessment and supervised reintroduction planning are needed.')],
 'TB drug-induced liver injury requires active management', '**Isoniazid, rifampicin and pyrazinamide can cause hepatotoxicity.**',['Investigate viral, obstructive and other hepatic causes.','Severe illness may require a specialist temporary nonhepatotoxic regimen.'], '**Reintroduce or replace drugs through a supervised protocol.**',['The pattern, severity and recovery affect the plan.','Do not leave serious active TB untreated without arranging an effective alternative.'],[['Symptoms','Anorexia, vomiting and jaundice'],['Possible drugs','H, R and Z'],['Plan','Stop culprit risk, assess and reconstruct safely']],[OT,AE],style='clinical_scenario')
q('Which mechanism best explains many rifampicin drug interactions?', 'Induction of drug-metabolizing enzymes and transport pathways',[
 ('Universal inhibition of all renal clearance','That is not the principal interaction mechanism.'),('Binding only to calcium in the gut','That is a different type of interaction.'),('Direct destruction of every coadministered drug in the tablet','The major interactions occur through altered handling in the body.')],
 'Rifamycins can substantially reduce exposure to interacting medicines', '**Review ART, anticoagulants, contraception and other affected drugs.**',['The size and consequence of an interaction are drug-specific.','Rifabutin can be useful in selected interaction-management strategies but is not interchangeable without review.'], '**Plan the whole regimen before starting or stopping a rifamycin.**',['Enzyme effects can persist after discontinuation.','Use validated dose adjustments or alternatives rather than guessing.'],[['Mechanism','Enzyme/transporter induction'],['Effect','Often lowers co-medication exposure'],['Management','Drug-specific review']],[OT])
q('A patient reports orange urine and tears after starting rifampicin, without systemic illness or organ injury. What is the best explanation?', 'Expected discoloration from the rifamycin, with counseling about staining',[
 ('It always proves severe intravascular hemolysis','Hemolysis needs compatible clinical and laboratory evidence.'),('It automatically establishes hepatitis','Color change alone is not diagnostic of hepatic injury.'),('It requires stopping every TB drug permanently','Expected discoloration alone is not that indication.')],
 'Counseling helps distinguish expected effects from dangerous symptoms', '**Rifampicin can discolor body fluids orange-red.**',['Soft contact lenses may stain.','Dark urine with jaundice or systemic symptoms needs separate urgent assessment.'], '**Explain warning signs rather than dismissing every color change.**',['Ask about appetite, abdominal symptoms, rash and bleeding.','Maintain adherence when the finding is an expected benign effect.'],[['Expected','Orange body-fluid discoloration'],['Warning','Jaundice or systemic illness'],['Counseling','Staining and adverse-event symptoms']],[AE],style='clinical_scenario')
q('Which first-line drug pair particularly needs dosing-interval review in severe renal impairment?', 'Pyrazinamide and ethambutol',[
 ('Isoniazid and rifampicin always require the same reduction as ethambutol','Their usual renal handling and adjustment needs differ.'),('Every TB drug can be dosed without reference to renal function','Accumulation can cause toxicity.'),('Only pyridoxine needs review, never the anti-TB agents','The actual treatment drugs need assessment.')],
 'Renal impairment changes exposure to selected TB drugs or metabolites', '**Ethambutol accumulation increases optic toxicity risk.**',['Pyrazinamide metabolites also accumulate.','Hemodialysis timing can affect administration planning.'], '**Use a renal-specific treatment protocol.**',['Do not reduce all drugs indiscriminately and risk inadequate exposure.','Monitor vision, symptoms and treatment response.'],[['Ethambutol','Renal accumulation concern'],['Pyrazinamide','Metabolite accumulation'],['Regimen','Drug-specific adjustment and dialysis timing']],[OT])
q('Which TB drug is classically contraindicated in pregnancy because of fetal ototoxicity risk?', 'Streptomycin',[
 ('Isoniazid in every circumstance','It can be used when indicated with appropriate monitoring and pyridoxine.'),('Rifampicin in every circumstance','It is used in pregnancy treatment regimens.'),('Ethambutol in every circumstance','It is not subject to the same blanket fetal-ototoxicity contraindication.')],
 'Active TB in pregnancy requires treatment with an appropriate regimen', '**Streptomycin can damage fetal hearing.**',['Untreated disease also threatens the mother and fetus.','Drug selection follows the resistance pattern and pregnancy-specific guidance.'], '**Use specialist assessment for resistant or complex disease.**',['Pyrazinamide recommendations and regimen details vary by guideline context.','Do not defer active-disease care solely because of pregnancy.'],[['Avoid','Streptomycin'],['Reason','Fetal ototoxicity'],['Priority','Effective pregnancy-appropriate treatment']],[PG])
q('A patient feels well after six weeks of active-TB treatment and wants to stop. What is the best explanation?', 'Symptom improvement does not establish sterilizing cure; completing the prescribed effective regimen reduces relapse and resistance risk',[
 ('Symptoms are the only reliable treatment endpoint','Clinical response can precede microbiological cure.'),('One negative smear always permits stopping any regimen','It does not establish that the complete course is unnecessary.'),('Every interruption is harmless if treatment is restarted someday','Interruptions may compromise effectiveness and need formal reassessment.')],
 'Bacterial clearance requires more than early clinical improvement', '**Persisting subpopulations can remain after symptoms improve.**',['Treatment duration depends on the validated regimen and disease context.','Adverse effects should prompt review rather than unsupervised cessation.'], '**Address the reason the patient wants to stop.**',['Provide practical adherence support and shared planning.','Use programmatic follow-up and microbiological monitoring where indicated.'],[['Symptoms improve','Encouraging but incomplete endpoint'],['Completion','Reduces relapse risk'],['Barrier','Assess and support rather than blame']],[WT,DS],style='clinical_scenario')

